  "characters[char-fma-edward-elric].aliases[0]": "Alquimista de Acero",
  "characters[char-fma-edward-elric].rank": "Alquimista Estatal",
  "characters[char-fma-edward-elric].relationships[0].label": "Hermano menor, con quien busca recuperar sus cuerpos",
  "characters[char-fma-edward-elric].relationships[1].label": "Amiga de la infancia y mecánica de su automail; se casa con ella",
